-- GENERATED by gen_mxh3_resolvers.py -- models are generated, never hand-edited.
--   start view  : MAXI_HLTH_CLM_VW_DATA_AUTHORIZATION_REMARKS
--   spans       : 1 (0 climb, 1 cross) -- one LEFT JOIN each
--   real levels : W000=1 named/2 real
--   EVERY intervening level is its own join: only 52 of 1,812 climbs name
--   the direct parent, so a single multi-level join would read the wrong node.
--   Direction is classified FROM THE GRAPH (shred.parent_table_candidate),
--   never from the arrow token.
--   A cross exposes W###_N beside every value; the value is NULL unless the
--   match is UNIQUE, so a 1:N cross is COUNTED, not silently resolved.

with src as (
    select KEY_HASH, PARENT_KEY_HASH from {{ ref('stg_clm_authr') }}
)

select
    src.KEY_HASH as KEY_HASH,
    case when w000._N000 = 1 then w000._V000 else null end as W000_CLAIM_NUMBER,
    w000._N000 as W000_N
from src
left join (
    select
        c0.KEY_HASH as _JK000,
        count(*) as _N000,
        max(d0.CLAIM_NUMBER) as _V000
    from {{ ref('hop_clm') }} c0
    join {{ ref('stg_clm_cd') }} d0
        on c0.KEY_HASH = d0.PARENT_KEY_HASH   /* LCA -> other branch */
    group by c0.KEY_HASH
) w000 on src.PARENT_KEY_HASH = w000._JK000
